import pytest
from target import encrypt


def test_encrypt_returns_string():
    result = encrypt("hello", 2)
    assert isinstance(result, str)


def test_encrypt_positive_key():
    result = encrypt("hello", 3)
    assert isinstance(result, str)


def test_encrypt_raises_value_error_for_negative_key():
    with pytest.raises(ValueError, match="Height of grid can't be 0 or negative"):
        encrypt("hello", -1)


def test_encrypt_raises_value_error_for_zero_key():
    with pytest.raises(ValueError, match="Height of grid can't be 0 or negative"):
        encrypt("hello", 0)


def test_encrypt_key_1_returns_input():
    result = encrypt("hello", 1)
    assert result == "hello"


def test_encrypt_shorter_than_key_returns_input():
    result = encrypt("hi", 5)
    assert result == "hi"


def test_encrypt_basic_3x3():
    result = encrypt("HELLO", 3)
    assert isinstance(result, str)


def test_encrypt_longer_string_3x3():
    result = encrypt("HELLO WORLD", 3)
    assert isinstance(result, str)

