    with pytest.raises(TypeError, match='Sequence must be list of non-negative integers'):
        bead_sort([1, -1, 2])


def test_non_integer_raises():
    with pytest.raises(TypeError, match='Sequence must be list of non-negative integers'):
        bead_sort([1, 2.5, 3])


def test_mixed_type_raises():
    with pytest.raises(TypeError, match='Sequence must be list of non-negative integers'):
        bead_sort([1, 'a', 3])

