    # Non-palindrome: 1 -> 2 -> 3
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None

    head = Node(1)
    head.next = Node(2)
    head.next.next = Node(3)
    assert is_palindrome(head) is False


