    # Palindrome with duplicate values: 1 -> 1 -> 1
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None

    head = Node(1)
    head.next = Node(1)
    head.next.next = Node(1)
    assert is_palindrome(head) is True


def test_non_palindrome_duplicates():
    # Non-palindrome with duplicate values: 1 -> 2 -> 1 -> 2
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None

    head = Node(1)
    head.next = Node(2)
    head.next.next = Node(1)
    head.next.next.next = Node(2)
    assert is_palindrome(head) is False

