import pytest
from target import compute_bridges


def test_single_edge_bridge():
    """A graph with two nodes and one edge should have that edge as a bridge."""
    graph = {0: [1], 1: [0]}
    result = compute_bridges(graph)
    assert (0, 1) in result


def test_three_node_path_bridges():
    """A simple path of three nodes: 0-1-2. Both edges are bridges."""
    graph = {0: [1], 1: [0, 2], 2: [1]}
    result = compute_bridges(graph)
    assert (0, 1) in result
    assert (1, 2) in result


def test_triangle_no_bridges():
    """A triangle (3 nodes all connected) should have no bridges."""
    graph = {0: [1, 2], 1: [0, 2], 2: [0, 1]}
    result = compute_bridges(graph)
    assert len(result) == 0


def test_disconnected_graph():
    """A graph with two separate components, each having a bridge."""
    graph = {0: [1], 1: [0], 2: [3], 3: [2]}
    result = compute_bridges(graph)
    assert (0, 1) in result
    assert (2, 3) in result


def test_linear_chain():
    """A linear chain of four nodes: 0-1-2-3."""
    graph = {0: [1], 1: [0, 2], 2: [1, 3], 3: [2]}
    result = compute_bridges(graph)
    assert (0, 1) in result
    assert (1, 2) in result
    assert (2, 3) in result


def test_graph_with_cycle():
    """A cycle with a tail: 0-1-2-0 and 2-3. Only (2, 3) is a bridge."""
    graph = {0: [1, 2], 1: [0, 2], 2: [1, 0, 3], 3: [2]}
    result = compute_bridges(graph)
    assert (2, 3) in result
    assert len([b for b in result if b != (2, 3)]) == 0

