def test_single_vertex():
    """A graph with a single vertex has no bridges."""
    graph = {0: []}
    result = compute_bridges(graph)
    assert result == []


def test_two_vertices_one_edge():
    """Two vertices connected by a single edge: the edge is a bridge."""
    graph = {0: [1], 1: [0]}
    result = compute_bridges(graph)
    assert sorted(result) == [(0, 1)]


def test_triangle_no_bridges():
    """A triangle (3 vertices all connected) has no bridges."""
    graph = {0: [1, 2], 1: [0, 2], 2: [0, 1]}
    result = compute_bridges(graph)
    assert result == []


