    graph = {0: [1, 2], 1: [0, 2], 2: [1, 0, 3], 3: [2]}
    result = compute_bridges(graph)
    assert sorted(result) == [(2, 3)]


def test_self_loop_ignored():
    """A self-loop should not affect bridge detection."""
    graph = {0: [0]}
    result = compute_bridges(graph)
