    assert [1, 3, 4] in result


def test_multiple_combinations():
    result = array_sum_combinations([1, 2], [1, 2], [1, 2], 5)
    # 1+1+3 does not exist because third array only has 1,2; combinations are 1+1+1=3, 1+1+2=4, 2+1+1=4, 2+1+2=5, etc.
