    for combo in expected:
        assert combo in result


def test_target_exceeded():
    result = array_sum_combinations([5], [5], [5], 1)
    assert result == []


def test_exact_length_three():
    result = array_sum_combinations([1], [2], [3], 6)
    assert result == [[1, 2, 3]]


def test_duplicate_values_in_arrays():
    result = array_sum_combinations([1, 1], [2], [3], 6)
    assert [1, 2, 3] in result

