import pytest
from target import modular_exponential


def test_modular_exponential_basic():
    # Standard calculation: 2^3 % 5 = 8 % 5 = 3
    assert modular_exponential(2, 3, 5) == 3


def test_modular_exponential_zero_power():
    # Any number to the power of 0 is 1 (mod m)
    assert modular_exponential(7, 0, 10) == 1


def test_modular_exponential_zero_base():
    # 0 to any positive power is 0
    assert modular_exponential(0, 5, 13) == 0


def test_modular_exponential_negative_power():
    # The function should return -1 for negative exponents
    assert modular_exponential(2, -1, 5) == -1


def test_modular_exponential_large_exponent():
    # Using Fermat's Little Theorem: 2^(10) % 11 = 1
    assert modular_exponential(2, 10, 11) == 1


def test_modular_exponential_large_modulus():
    assert modular_exponential(123456, 789, 999983) == 123456 ** 789 % 999983


def test_modular_exponential_identity_base():
    # 1 to any power is 1
    assert modular_exponential(1, 100, 7) == 1


def test_modular_exponential_reduces_base():
    # The function takes base % mod at the start
    # 17 % 5 = 2, so 17^2 % 5 should equal 2^2 % 5 = 4
    assert modular_exponential(17, 2, 5) == 4

